export type MailyMailboxComposeSeedKind = 'reply' | 'replyAll' | 'forward';

/** Initial values for a reply or forward, and its In-Reply-To header. */
export type MailyMailboxComposeSeed = MailyMailboxComposeValues & {
  /** RFC Message-ID this composition answers; never a storage row ID. */
  inReplyTo?: string | null;
};

export type MailyMailboxComposeSeedContext = {
  account?: MailyMailboxAccount;
  labels: MailyMailboxLabels;
  formatDate: (date: string | Date, mode: 'short' | 'long') => string;
};

function interpolate(label: string, vars: Record<string, string>) {
  return label.replace(
    /\{(\w+)\}/g,
    (match, key: string) => vars[key] ?? match
  );
}

function subjectWithPrefix(prefix: 'Re:' | 'Fwd:', subject: string | null) {
  const clean = subject?.trim() || '';
  if (!clean) return prefix;
  return clean.toLowerCase().startsWith(prefix.toLowerCase())
    ? clean
    : `${prefix} ${clean}`;
}

function quotedBody(text: string | null | undefined) {
  return (text ?? '')
    .split('\n')
    .map((line) => `> ${line}`)
    .join('\n');
}

/**
 * Maily's default reply and forward values: `Re:`/`Fwd:` subjects, a quoted
 * plain-text body, Reply all without the account's own address, and the
 * original's Message-ID as In-Reply-To. Hosts with other conventions pass
 * `createComposeSeed`, and can call this for the parts they keep.
 */
export function defaultMailboxComposeSeed(
  kind: MailyMailboxComposeSeedKind,
  message: MailyMailboxMessageDetail,
  context: MailyMailboxComposeSeedContext
): MailyMailboxComposeSeed {
  const { labels } = context;
  if (kind === 'forward') {
    const header = [
      `---------- ${labels['compose.forwardedHeader']} ----------`,
      `${labels['compose.forwardFrom']}: ${message.fromAddress}`,
      `${labels['compose.forwardTo']}: ${(message.toAddresses ?? []).join(', ')}`,
      `${labels['compose.forwardSubject']}: ${message.subject ?? ''}`,
    ].join('\n');
    return {
      to: '',
      cc: '',
      bcc: '',
      subject: subjectWithPrefix('Fwd:', message.subject),
      text: `\n\n${header}\n\n${message.bodyText ?? ''}`,
      html: null,
      inReplyTo: null,
    };
  }
  const intro = interpolate(labels['compose.wrote'], {
    date: context.formatDate(message.createdAt, 'long'),
    sender: message.fromAddress,
  });
  const recipients =
    kind === 'replyAll'
      ? getMailboxReplyAllRecipients(message, [context.account?.address])
      : { to: [message.fromAddress], cc: [] };
  return {
    to: recipients.to.join(', '),
    cc: recipients.cc.join(', '),
    bcc: '',
    subject: subjectWithPrefix('Re:', message.subject),
    text: `\n\n${intro}\n${quotedBody(message.bodyText)}`,
    html: null,
    // A storage row ID is not an RFC Message-ID. Mail without that header
    // remains replyable, but cannot supply an In-Reply-To header.
    inReplyTo: message.messageId || null,
  };
}

export type MailyMailboxContactSuggestion = {
  id?: string;
  address: string;
  displayName?: string | null;
};

function contactSuggestionSearchText(
  suggestion: MailyMailboxContactSuggestion
): string {
  return [suggestion.displayName ?? '', suggestion.address]
    .join(' ')
    .toLowerCase();
}

export function filterMailboxContactSuggestions(
  contacts: MailyMailboxContactSuggestion[],
  q?: string,
  limit = 8
): MailyMailboxContactSuggestion[] {
  const query = (q ?? '').trim().toLowerCase();
  if (!query) return contacts.slice(0, limit);

  const seen = new Set<string>();
  const matches: MailyMailboxContactSuggestion[] = [];

  for (const contact of contacts) {
    const key = contact.address.trim().toLowerCase();
    if (!key || seen.has(key)) continue;
    if (!contactSuggestionSearchText(contact).includes(query)) continue;

    seen.add(key);
    matches.push(contact);
    if (matches.length >= limit) break;
  }

  return matches;
}

export type MailyMailboxThreadedMessage = {
  id: string;
  threadId?: string | null;
  fromAddress: string;
  toAddresses: readonly string[];
  ccAddresses?: readonly string[] | null;
  subject: string | null;
  createdAt: string | Date;
  isUnread?: boolean;
};

export type MailyMailboxConversation<T extends MailyMailboxThreadedMessage> = {
  /** Null means this message had no host-provided thread ID and is a singleton. */
  threadId: string | null;
  messages: T[];
  latestAt: Date;
  subject: string | null;
  participants: string[];
  unreadCount: number;
};

/** Groups only by host-supplied threadId; missing IDs always remain singletons. */
export function groupMailboxMessagesByThread<
  T extends MailyMailboxThreadedMessage,
>(messages: readonly T[]): MailyMailboxConversation<T>[] {
  const groups = new Map<string, { threadId: string | null; messages: T[] }>();
  for (const [index, message] of messages.entries()) {
    const threadId = message.threadId?.trim() || null;
    // Separate namespaces keep host IDs distinct from unthreaded message IDs.
    const key = threadId
      ? `thread:${threadId}`
      : `message:${index}:${message.id}`;
    const group = groups.get(key) ?? { threadId, messages: [] };
    group.messages.push(message);
    groups.set(key, group);
  }

  return [...groups.values()].map(({ threadId, messages: groupMessages }) =>
    getMailboxConversationMetadata(threadId, groupMessages)
  );
}

export function getMailboxConversationMetadata<
  T extends MailyMailboxThreadedMessage,
>(
  threadId: string | null,
  messages: readonly T[]
): MailyMailboxConversation<T> {
  const ordered = [...messages].sort(
    (a, b) => toDate(a.createdAt).getTime() - toDate(b.createdAt).getTime()
  );
  const latest = ordered[ordered.length - 1];
  const seen = new Set<string>();
  const participants: string[] = [];
  for (const message of ordered) {
    for (const address of [
      message.fromAddress,
      ...message.toAddresses,
      ...(message.ccAddresses ?? []),
    ]) {
      const trimmed = address.trim();
      const key = trimmed.toLocaleLowerCase('en-US');
      if (!trimmed || seen.has(key)) continue;
      seen.add(key);
      participants.push(trimmed);
    }
  }
  return {
    threadId,
    messages: ordered,
    latestAt: latest ? toDate(latest.createdAt) : new Date(0),
    subject: latest?.subject ?? null,
    participants,
    unreadCount: ordered.filter((message) => message.isUnread).length,
  };
}

function toDate(value: string | Date): Date {
  return value instanceof Date ? new Date(value.getTime()) : new Date(value);
}

/**
 * Draft operations a host can allow independently while the mailbox stays
 * mounted. Each one also requires its data-source callback.
 */
export type MailyMailboxDraftCapabilities = {
  /** Persist a new composition with `createDraft`: Compose, Reply, Reply all, Forward. */
  create?: boolean;
  /** Persist changes to an existing draft with `updateDraft`. */
  edit?: boolean;
  /** Deliver a saved draft with `sendDraft`, or a new composition with `sendMessage`. */
  send?: boolean;
  /** Delete a persisted draft with `discardDraft`. */
  discard?: boolean;
};

export type MailyMailboxDraftCapability = keyof MailyMailboxDraftCapabilities;

export type MailboxDraftCapabilities = Record<
  MailyMailboxDraftCapability,
  boolean
> & {
  /** A new composition can be sent with `sendMessage`, without a saved draft. */
  sendMessage: boolean;
};

type DraftCallbacks = {
  createDraft?: unknown;
  updateDraft?: unknown;
  sendDraft?: unknown;
  sendMessage?: unknown;
  discardDraft?: unknown;
};

/** `false` withholds an operation; no value can enable a missing callback. */
export function resolveMailboxDraftCapabilities(
  dataSource: DraftCallbacks,
  requested: MailyMailboxDraftCapabilities = {}
): MailboxDraftCapabilities {
  const send = requested.send !== false;
  return {
    create:
      requested.create !== false &&
      typeof dataSource.createDraft === 'function',
    edit:
      requested.edit !== false && typeof dataSource.updateDraft === 'function',
    send: send && typeof dataSource.sendDraft === 'function',
    sendMessage: send && typeof dataSource.sendMessage === 'function',
    discard:
      requested.discard !== false &&
      typeof dataSource.discardDraft === 'function',
  };
}

/** Compose, Reply, Reply all and Forward need a way to keep or send the result. */
export function canStartComposition(capabilities: MailboxDraftCapabilities) {
  return capabilities.create || capabilities.sendMessage;
}

export type MailboxComposeState = {
  /** The composition already has a host draft ID. */
  persisted: boolean;
  /** Local content differs from the last acknowledged write, or uploads are pending. */
  dirty: boolean;
};

export type MailboxComposeOperations = {
  /** Fields accept input. Unsaved local work is never locked. */
  editable: boolean;
  /** Save draft. */
  save: boolean;
  /** Attachment uploads: the result can be saved or sent. */
  attach: boolean;
  /** Every later autosave edits the draft, including one the first save creates. */
  autosave: boolean;
  /** Saved drafts without edit can only be sent unchanged. */
  send: boolean;
  /** Unsaved compositions close locally; persisted drafts need `discardDraft`. */
  discard: boolean;
};

export function getMailboxComposeOperations(
  capabilities: MailboxDraftCapabilities,
  { persisted, dirty }: MailboxComposeState
): MailboxComposeOperations {
  const save = persisted ? capabilities.edit : capabilities.create;
  const sendNew =
    capabilities.sendMessage || (capabilities.create && capabilities.send);

  return {
    editable: save || dirty || (!persisted && sendNew),
    save,
    attach: save || (!persisted && sendNew),
    autosave: capabilities.edit && (persisted || capabilities.create),
    send: persisted
      ? capabilities.send && (capabilities.edit || !dirty)
      : sendNew,
    discard: persisted ? capabilities.discard : true,
  };
}

