      let start = 1;
      let total: number | undefined;
      for (let index = 0; index <= currentIndex; index += 1) {
        const page = await dataSource.listMessages({
          folder: listFolder,
          q: serializedSearch,
          search: structuredSearch,
          labelId: selectedLabelId ?? undefined,
          cursor,
          limit: pageSize,
