    [
      listFolder,
      dataSource,
      serializedSearch,
      structuredSearch,
      selectedLabelId,
      pageSize,
      bulkSelectionControlled,
      setSelectedIds,
      readerSelectionControlled,
      composeDraftRef,
      setSelectedId,
