    if (!acceptedByHost || !bulkSelectionControlled) setSelectedIds([]);
    if (!acceptedByHost || !readerSelectionControlled) setSelectedId(null);
    setComposeOpen(false);
    setComposeDraftId(null);
    setComposeSeed(null);
    setComposeInReplyTo(null);
