      if (!readerSelectionControlled && !composeDraftRef.current)
        setSelectedId(null);
    }
  }, [
    queryKey,
    props.selectedMessageIds,
    props.selectedMessageId,
    setSelectedIds,
    setSelectedId,
    bulkSelectionControlled,
    readerSelectionControlled,
    composeDraftRef,
