        ) : values.text.trim() ? (
          <pre className="p-3 font-sans text-sm leading-relaxed [overflow-wrap:anywhere] break-words whitespace-pre-wrap">
            {values.text}
          </pre>
        ) : (
          <p className="text-muted-foreground p-3 text-sm">
