import type { MailyMailboxFolder, MailyMailboxMessageAction } from './types';

/** Where message actions are offered, passed to a `messageActions` function. */
export type MailyMailboxMessageActionContext = {
  /**
   * `reader`: the open message. `bulk`: the selected list rows. `list`: the
   * per-row star (favorite) control.
   */
  surface: 'reader' | 'bulk' | 'list';
  /** The folder in view. */
  folder: MailyMailboxFolder;
  /** The label in view, if any. */
  labelId: string | null;
  /** Whether a search spans the folder in view or all mail. */
  searchScope: 'folder' | 'allMail';
  /** Whether a search text or filter is active. */
  searching: boolean;
  /** The messages the actions apply to; empty for `list`. */
  messageIds: readonly string[];
};

const LEAVE_SPAM_AND_TRASH = new Set<MailyMailboxMessageAction>([
  'delete',
  'reportSpam',
]);

/**
 * Gmail-style folder rules, for hosts that want them: Archive in Inbox, Not
 * spam in Spam, Delete forever in Trash and Spam, Move to Inbox in Trash, All
 * Mail and Starred, and no Delete or Report spam inside Trash or Spam. A search
 * across all mail behaves like All Mail. Maily applies no rules of its own:
 * pass `messageActions={(context) => defaultMailboxMessageActionsFor(context, actions)}`.
 */
export function defaultMailboxMessageActionsFor(
  context: MailyMailboxMessageActionContext,
  actions: readonly MailyMailboxMessageAction[]
): MailyMailboxMessageAction[] {
  const allMail = context.searching && context.searchScope === 'allMail';
  const folder = allMail ? 'allMail' : context.folder;
  const inSpamOrTrash = folder === 'spam' || folder === 'trash';
  return actions.filter((action) => {
    if (action === 'archive') return folder === 'inbox';
    if (action === 'notSpam') return folder === 'spam';
    if (action === 'deleteForever') return inSpamOrTrash;
    if (action === 'restore')
      return folder === 'trash' || folder === 'allMail' || folder === 'starred';
    if (LEAVE_SPAM_AND_TRASH.has(action)) return !inSpamOrTrash;
    return true;
  });
}

import { mailboxAddressOf } from './addresses';

/** Minimal recipient shape accepted by reply-all calculation. Bcc is deliberately absent. */
export type MailyMailboxReplyAllInput = {
  fromAddress: string;
  toAddresses?: readonly string[] | null;
  ccAddresses?: readonly string[] | null;
};

export type MailyMailboxReplyAllRecipients = {
  to: string[];
  cc: string[];
};

/**
 * Builds Reply all recipients: sender and original To recipients stay in To;
 * original Cc recipients stay in Cc.
 * Account addresses and duplicates are compared case-insensitively. Bcc is never
 * read or returned, so it cannot be disclosed by this helper.
 */
export function getMailboxReplyAllRecipients(
  message: MailyMailboxReplyAllInput,
  ownAddresses: readonly (string | null | undefined)[] = []
): MailyMailboxReplyAllRecipients {
  const own = new Set(
    ownAddresses
      .filter((address): address is string => typeof address === 'string')
      .map(normalizeAddress)
      .filter((address) => address.length > 0)
  );
  const sender = message.fromAddress.trim();
  const to: string[] = [];
  const cc: string[] = [];
  const seen = new Set(own);
  appendUnique(to, sender ? [sender] : [], seen);
  appendUnique(to, message.toAddresses ?? [], seen);
  appendUnique(cc, message.ccAddresses ?? [], seen);

  return { to, cc };
}

function normalizeAddress(address: string): string {
  return mailboxAddressOf(address).toLocaleLowerCase('en-US');
}

function appendUnique(
  output: string[],
  addresses: readonly string[],
  seen: Set<string>
): void {
  for (const address of addresses) {
    const trimmed = address.trim();
    const key = normalizeAddress(trimmed);
    if (!trimmed || !key || seen.has(key)) continue;
    seen.add(key);
    output.push(trimmed);
  }
}

/** Structured, provider-neutral search inputs for a caller-owned mailbox adapter. */
export type MailyMailboxSearchQuery = {
  text?: string;
  from?: string;
  to?: string;
  subject?: string;
  after?: string;
  before?: string;
  unread?: boolean;
  starred?: boolean;
  hasAttachments?: boolean;
  labelId?: string | null;
};

/** Advanced filters, in the order the search form shows them. */
export const MAILBOX_SEARCH_FILTERS = [
  'from',
  'to',
  'subject',
  'after',
  'before',
  'hasAttachments',
  'unread',
] as const;

export type MailyMailboxSearchFilter = (typeof MAILBOX_SEARCH_FILTERS)[number];

/**
 * Advanced filters the host's backend supports. Each is off unless set to
 * `true`. Text search does not depend on these.
 */
export type MailyMailboxSearchCapabilities = {
  /** Sender address or name: `search.from`. */
  from?: boolean;
  /** Recipient address or name: `search.to`. */
  to?: boolean;
  /** Subject text: `search.subject`. */
  subject?: boolean;
  /** Messages on or after a date, as typed: `search.after`. */
  after?: boolean;
  /** Messages before a date, as typed: `search.before`. */
  before?: boolean;
  /** Only messages with attachments: `search.hasAttachments`. */
  hasAttachments?: boolean;
  /** Only unread messages: `search.unread`. */
  unread?: boolean;
};

/** The enabled advanced filters, in form order. */
export function resolveMailboxSearchFilters(
  capabilities: MailyMailboxSearchCapabilities = {}
): MailyMailboxSearchFilter[] {
  return MAILBOX_SEARCH_FILTERS.filter((key) => capabilities[key] === true);
}

/**
 * Drops values of advanced filters that are not enabled. Text, `starred` and
 * `labelId` are not advanced form filters and pass through. Returns the input
 * object when nothing is dropped.
 */
export function withEnabledSearchFilters<T extends MailyMailboxSearchQuery>(
  query: T,
  enabled: readonly MailyMailboxSearchFilter[]
): T {
  const disabled = MAILBOX_SEARCH_FILTERS.filter(
    (key) => !enabled.includes(key) && key in query
  );
  if (!disabled.length) return query;
  const next = { ...query };
  for (const key of disabled) delete next[key];
  return next;
}

/**
 * Serializes supported filters into Gmail-style query syntax for adapters whose
 * backend accepts this format. Other adapters can consume the structured type
 * directly and ignore this serializer.
 */
export function buildMailboxSearchQuery(
  query: MailyMailboxSearchQuery
): string {
  const terms: string[] = [];
  const add = (operator: string, value: string | undefined) => {
    const normalized = value?.trim();
    if (normalized) terms.push(`${operator}${quoteSearchValue(normalized)}`);
  };

  // Free text is an advanced query expression; preserve operators such as from:.
  if (query.text?.trim()) terms.push(query.text.trim());
  add('from:', query.from);
  add('to:', query.to);
  add('subject:', query.subject);
  add('after:', query.after);
  add('before:', query.before);
  if (query.unread) terms.push('is:unread');
  if (query.starred) terms.push('is:starred');
  if (query.hasAttachments) terms.push('has:attachment');
  add('label:', query.labelId ?? undefined);
  return terms.join(' ');
}

function quoteSearchValue(value: string): string {
  if (!/[\s"\\]/.test(value)) return value;
  return `"${value.replace(/["\\]/g, '\\$&')}"`;
}

